'use client'

import * as React from 'react'

import { useOffscreen } from './use-reduced-motion'
import './halo-glow.css'

export type HaloGlowProps = {
    /** The content the halo sits behind, e.g. a logo, avatar or button. */
    children: React.ReactNode
    colors?: string[]
    /** Seconds per turn. */
    speed?: number
    /** Halo size relative to the content. */
    spread?: number
    paused?: boolean
    className?: string
}

// A slowly turning, blurred conic gradient behind any element.
const HaloGlow = ({ children, colors = ['#8b5cf6', '#22d3ee', '#f472b6', '#8b5cf6'], speed = 8, spread = 1.4, paused = false, className }: HaloGlowProps) => {
    const ref = React.useRef<HTMLSpanElement | null>(null)
    const offscreen = useOffscreen(ref)

    return <span
        ref={ref}
        className={['rad-fx-halo', className].filter(Boolean).join(' ')}
        data-state={paused || offscreen ? 'paused' : 'running'}
        style={{
            '--rad-fx-halo-gradient': `conic-gradient(from 0deg, ${colors.join(', ')})`,
            '--rad-fx-halo-speed': `${speed}s`,
            '--rad-fx-halo-spread': spread
        } as React.CSSProperties}
    >
        <span className="rad-fx-halo-ring" aria-hidden="true" />
        <span className="rad-fx-halo-content">{children}</span>
    </span>
}

export default HaloGlow

.rad-fx-halo {
    position: relative;
    display: inline-grid;
    place-items: center;
    isolation: isolate;
}

.rad-fx-halo-ring {
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: 50%;
    background: var(--rad-fx-halo-gradient);
    filter: blur(28px);
    opacity: 0.75;
    transform: scale(var(--rad-fx-halo-spread, 1.4));
    animation: rad-fx-halo var(--rad-fx-halo-speed, 8s) linear infinite;
    pointer-events: none;
}

.rad-fx-halo[data-state='paused'] .rad-fx-halo-ring { animation-play-state: paused; }

.rad-fx-halo-content { position: relative; }

@keyframes rad-fx-halo {
    from { transform: scale(var(--rad-fx-halo-spread, 1.4)) rotate(0deg); }
    to { transform: scale(var(--rad-fx-halo-spread, 1.4)) rotate(360deg); }
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-halo-ring { animation: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-halo-ring { animation: none; }
